for f in files:
 print(f.get(\"accession\"), f.get(\"file_format\"), f.get(\"output_type\"), f.get(\"biological_replicates\"), f.get(\"status\"), f.get(\"assembly\"), f.get(\"lab\"), f.get(\"href\"))
'"

