/bin/bash -lc "cd /workspace && python3 - <<'PY'
import csv
with open('afgr_experiment_metadata.tsv', newline='') as f:
    r=csv.DictReader(f, delimiter='\\t')
    for row in r:
        if row['File accession']=='ENCFF321SNO':
            for k,v in row.items(): print(k, ':', v)
            break
PY"

